const https = require('https');

// Helper function to read environment variables directly from the file
function readEnvVariables(filePath) {
  const fs = require('fs');
  const envConfig = fs.readFileSync(filePath, 'utf-8');

  const configs = {};
  const lines = envConfig.split('\n');
  lines.forEach((line) => {
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      configs[key] = value;
    }
  });

  return configs;
}

// Function to post environment variables to the backup endpoint
function backupConfigs() {
  const backupEndpoint = 'http://localhost:47301/api/dr-backup';
  const configs = readEnvVariables('.env.test');

  const postData = JSON.stringify(configs);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/dr-backup',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData),
    },
  };

  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', (chunk) => {
      data += chunk;
    });
    res.on('end', () => {
      console.log('✅ Backup successful:', data);
    });
  });

  req.on('error', (err) => {
    console.error('❌ Backup failed:', err.message);
  });

  req.write(postData);
  req.end();
}

// Main function
function main() {
  console.log('Starting backup of environment variables...\n');
  backupConfigs();
  console.log('\nBackup process complete.');
}

main();

