// Script to verify environment variables and connectivity
// Note: This script is for testing purposes and assumes synthetic credentials

const { Pool } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch');
const stripe = require('stripe');

require('dotenv').config({ path: '.env.test' });

// Initialize logger for structured output
const log = (message, data = {}) => {
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), message, ...data }));
};

// Database connectivity check
const checkDatabase = async () => {
  try {
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: 2000,
    });
    const client = await pool.connect();
    await client.query('SELECT 1');
    await client.release();
    log('Database connectivity check passed');
    return true;
  } catch (err) {
    const errorDetails = {
      name: err.name,
      code: err.code,
      detail: err.detail || err.message,
    };
    if (err.connection && err.connection._closing) {
      errorDetails.connectionError = 'Connection failed during handshake';
    }
    log('Database connectivity check failed', errorDetails);
    return false;
  }
};

// AWS credentials check
const checkAWS = async () => {
  try {
    const s3 = new AWS.S3({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1',
      signatureVersion: 'v4',
      endpoint: 'https://s3.us-east-1.amazonaws.com',
    });
    const HttpRequest = require('http-request');
    const endpoint = new AWS.Endpoint('s3.us-east-1.amazonaws.com');
    const request = new HttpRequest(endpoint);
    request.method = 'GET';
    request.path = '/'
    s3.signRequest(request, {});
    if (request.headers.Authorization) {
      log('AWS credentials format check passed');
      return true;
    } else {
      throw new Error('Authorization header missing');
    }
  } catch (err) {
    log('AWS credentials check failed', { error: err.message });
    return false;
  }
};

// Anthropic API check (mock)
const checkAnthropic = async () => {
  try {
    const response = await fetch('https://api.anthropic.com/v1/', {
      headers: {
        'Authorization': `Bearer ${process.env.ANTHROPIC_API_KEY}`,
      },
      method: 'GET',
    });
    log('Anthropic API check passed', { status: response.status });
    return true;
  } catch (err) {
    log('Anthropic API check failed', { error: err.message });
    return false;
  }
};

// Stripe API check (mock)
const checkStripe = async () => {
  try {
    const client = stripe(process.env.STRIPE_SECRET_KEY);
    const response = await client.customers.list({ limit: 1 });
    log('Stripe API check passed');
    return true;
  } catch (err) {
    log('Stripe API check failed', { error: err.message });
    return false;
  }
};

// Main
(async () => {
  log('Starting verification of environment variables...');

  const results = {
    DATABASE_URL: await checkDatabase(),
    AWS_ACCESS_KEY_ID: await checkAWS(),
    ANTHROPIC_API_KEY: await checkAnthropic(),
    STRIPE_SECRET_KEY: await checkStripe(),
  };

  log('Verification complete', { results });
})();

