// Script to verify environment variables and connectivity
// Note: This script is for testing purposes and assumes synthetic credentials

require('dotenv').config({ path: '.env.test' });

// Initialize logger for structured output
const log = (message, data = {}) => {
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), message, ...data }));
};

// Helper function to validate required environment variables
const validateRequiredVars = () => {
  const requiredVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];
  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    log('Missing environment variables', { missingVars });
    return false;
  }
  return true;
};

// Database connection string format validation
const validateDatabaseURL = () => {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl || !dbUrl.startsWith('postgres://')) {
    log('Database URL is invalid or missing');
    return false;
  }
  return true;
};

// AWS key format validation
const validateAWSKeys = () => {
  const accessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyRegex = /^([^\s]+)$/;

  if (!accessKeyRegex.test(process.env.AWS_ACCESS_KEY_ID)) {
    log('Invalid AWS_ACCESS_KEY_ID format');
    return false;
  }

  if (!secretKeyRegex.test(process.env.AWS_SECRET_ACCESS_KEY) || process.env.AWS_SECRET_ACCESS_KEY.length < 20) {
    log('Invalid AWS_SECRET_ACCESS_KEY format or length');
    return false;
  }

  return true;
};

// Anthropic API key format validation
const validateAnthropicKey = () => {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key || !key.startsWith('sk-ant-') || key.length < 20) {
    log('Invalid ANTHROPIC_API_KEY format');
    return false;
  }
  return true;
};

// Stripe key format validation
const validateStripeKey = () => {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key || !key.startsWith('sk_live_') && !key.startsWith('sk_test_') || key.length < 20) {
    log('Invalid STRIPE_SECRET_KEY format');
    return false;
  }
  return true;
};

// Main
(async () => {
  log('Starting verification of environment variables...');

  const results = {
    requiredVarsPresent: validateRequiredVars(),
    DATABASE_URL: validateDatabaseURL(),
    AWS_ACCESS_KEY_ID: validateAWSKeys(),
    ANTHROPIC_API_KEY: validateAnthropicKey(),
    STRIPE_SECRET_KEY: validateStripeKey(),
  };

  log('Verification complete', { results });
})();

